INSERT INTO coding_session_activity(
    session_id, schema_version, project_id, tenant_id, principal_id, principal_type,
    display_name, session_status, active_run_id, active_run_version, active_dispatch_key,
    created_at_ms, last_activity_at_ms, revision
) VALUES (
    #{row.sessionId}, #{row.schemaVersion}, #{row.projectId}, #{row.tenantId},
    #{row.principalId}, #{row.principalType}, #{row.displayName}, #{row.sessionStatus}, #{row.activeRunId},
    #{row.activeRunVersion}, #{row.activeDispatchKey}, #{row.createdAt},
    #{row.lastActivityAt}, #{row.revision}
)

mapper.select:
SELECT * FROM coding_session_activity
WHERE tenant_id = #{tenantId}
  AND principal_id = #{principalId}
  AND principal_type = #{principalType}
  AND project_id = #{projectId}
  AND session_status != 'DELETED'

  AND (lower(display_name) LIKE #{textLike} ESCAPE '\'
       OR lower(session_id) LIKE #{textLike} ESCAPE '\')


  AND (last_activity_at_ms < #{afterAt}
       OR (last_activity_at_ms = #{afterAt} AND session_id < #{afterSessionId}))

ORDER BY last_activity_at_ms DESC, session_id DESC
LIMIT #{limit}

mapper.update:
UPDATE coding_session_activity
SET active_run_id = NULL, active_run_version = NULL, active_dispatch_key = NULL,
    last_activity_at_ms = #{updatedAt}, revision = revision + 1
WHERE session_id = #{sessionId} AND active_run_id = #{runId}
  AND revision = #{expectedRevision}
